def is_prime(num):
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0:
        return False
    sqrt_num = math.sqrt(num)
    for i in range(3, int(sqrt_num) + 1, 2):
        if num % i == 0:
            return False
    return True
